@Test
public void toEnumValue() {
    final AbstractJavaCodegen codegen = new P_AbstractJavaCodegen();
    Assert.assertEquals(codegen.toEnumValue("1", "Integer"), "1");
    Assert.assertEquals(codegen.toEnumValue("42", "Double"), "42");
    Assert.assertEquals(codegen.toEnumValue("1337", "Long"), "1337l");
    Assert.assertEquals(codegen.toEnumValue("3.14", "Float"), "3.14f");
    Assert.assertEquals(codegen.toEnumValue("12.34", "BigDecimal"), "new BigDecimal(\"12.34\")");
    Assert.assertEquals(codegen.toEnumValue("https://example.com/path", "URI"),
            "URI.create(\"https://example.com/path\")");
}

@Test
    public void convertModelName() {
        assertEquals(codegen.toModelName("$"), "Dollar");
        assertEquals(codegen.toModelName("$$"), "DollarDollar");
        assertEquals(codegen.toModelName("Pony?"), "PonyQuestionMark");
        assertEquals(codegen.toModelName("$name"), "DollarName");
        assertEquals(codegen.toModelName("nam#e"), "NamHashE");
        assertEquals(codegen.toModelName("$another-fake?"), "DollarAnotherFakeQuestionMark");
        assertEquals(codegen.toModelName("Pony>=>="), "PonyGreaterThanEqualGreaterThanEqual");
    }

@Test
public void testToEnumName() {
    Function<String, String> toEnumName = (String name) -> {
        CodegenProperty property = new CodegenProperty();
        property.baseName = name;
        return codegen.toEnumName(property);
    };
    // Should be converted to camel case
    Assert.assertEquals(toEnumName.apply("pet_status"), "PetStatusWithSuffix");
    // Prefix is added when starting with a number
    Assert.assertEquals(toEnumName.apply("1_pet_status"), "Enum1PetStatusWithSuffix");
}

