@Test
public void testGenPartitionFromQueueData() throws Exception {
    // test queueData with 8 read queues, 8 write queues, and rw permission, expect 8 rw queues.
    QueueData queueDataWith8R8WPermRW = createQueueData(8, 8, PermName.PERM_READ | PermName.PERM_WRITE);
    List<MessageQueue> partitionWith8R8WPermRW = this.routeActivity.genMessageQueueFromQueueData(queueDataWith8R8WPermRW, GRPC_TOPIC, TopicMessageType.NORMAL, GRPC_BROKER);
    assertEquals(8, partitionWith8R8WPermRW.size());
    assertEquals(8, partitionWith8R8WPermRW.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.NORMAL.getNumber()).count());
    assertEquals(8, partitionWith8R8WPermRW.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
    assertEquals(0, partitionWith8R8WPermRW.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith8R8WPermRW.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(0, partitionWith8R8WPermRW.stream().filter(a -> a.getPermission() == Permission.NONE).count());

    // test queueData with 8 read queues, 8 write queues, and read only permission, expect 8 read only queues.
    QueueData queueDataWith8R8WPermR = createQueueData(8, 8, PermName.PERM_READ);
    List<MessageQueue> partitionWith8R8WPermR = this.routeActivity.genMessageQueueFromQueueData(queueDataWith8R8WPermR, GRPC_TOPIC, TopicMessageType.FIFO, GRPC_BROKER);
    assertEquals(8, partitionWith8R8WPermR.size());
    assertEquals(8, partitionWith8R8WPermR.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.FIFO.getNumber()).count());
    assertEquals(8, partitionWith8R8WPermR.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith8R8WPermR.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
    assertEquals(0, partitionWith8R8WPermR.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(0, partitionWith8R8WPermR.stream().filter(a -> a.getPermission() == Permission.NONE).count());

    // test queueData with 8 read queues, 8 write queues, and write only permission, expect 8 write only queues.
    QueueData queueDataWith8R8WPermW = createQueueData(8, 8, PermName.PERM_WRITE);
    List<MessageQueue> partitionWith8R8WPermW = this.routeActivity.genMessageQueueFromQueueData(queueDataWith8R8WPermW, GRPC_TOPIC, TopicMessageType.TRANSACTION, GRPC_BROKER);
    assertEquals(8, partitionWith8R8WPermW.size());
    assertEquals(8, partitionWith8R8WPermW.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.TRANSACTION.getNumber()).count());
    assertEquals(8, partitionWith8R8WPermW.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(0, partitionWith8R8WPermW.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
    assertEquals(0, partitionWith8R8WPermW.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith8R8WPermW.stream().filter(a -> a.getPermission() == Permission.NONE).count());

    // test queueData with 8 read queues, 0 write queues, and rw permission, expect 8 read only queues.
    QueueData queueDataWith8R0WPermRW = createQueueData(8, 0, PermName.PERM_READ | PermName.PERM_WRITE);
    List<MessageQueue> partitionWith8R0WPermRW = this.routeActivity.genMessageQueueFromQueueData(queueDataWith8R0WPermRW, GRPC_TOPIC, TopicMessageType.DELAY, GRPC_BROKER);
    assertEquals(8, partitionWith8R0WPermRW.size());
    assertEquals(8, partitionWith8R0WPermRW.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.DELAY.getNumber()).count());
    assertEquals(8, partitionWith8R0WPermRW.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith8R0WPermRW.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
    assertEquals(0, partitionWith8R0WPermRW.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(0, partitionWith8R0WPermRW.stream().filter(a -> a.getPermission() == Permission.NONE).count());

    // test queueData with 4 read queues, 8 write queues, and rw permission, expect 4 rw queues and 4 write only queues.
    QueueData queueDataWith4R8WPermRW = createQueueData(4, 8, PermName.PERM_READ | PermName.PERM_WRITE);
    List<MessageQueue> partitionWith4R8WPermRW = this.routeActivity.genMessageQueueFromQueueData(queueDataWith4R8WPermRW, GRPC_TOPIC, TopicMessageType.UNSPECIFIED, GRPC_BROKER);
    assertEquals(8, partitionWith4R8WPermRW.size());
    assertEquals(8, partitionWith4R8WPermRW.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.MESSAGE_TYPE_UNSPECIFIED.getNumber()).count());
    assertEquals(4, partitionWith4R8WPermRW.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(4, partitionWith4R8WPermRW.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
    assertEquals(0, partitionWith4R8WPermRW.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith4R8WPermRW.stream().filter(a -> a.getPermission() == Permission.NONE).count());

    // test inaccessible queueData, expect queues with no permission.
    QueueData queueDataWith8R8WPermNone = createQueueData(8, 8, PermName.PERM_INHERIT);
    List<MessageQueue> partitionWith8R8WPermNone = this.routeActivity.genMessageQueueFromQueueData(queueDataWith8R8WPermNone, GRPC_TOPIC, TopicMessageType.NORMAL, GRPC_BROKER);
    assertEquals(8, partitionWith8R8WPermNone.size());
    assertEquals(8, partitionWith8R8WPermNone.stream().filter(a -> a.getAcceptMessageTypesValue(0) == MessageType.NORMAL.getNumber()).count());
    assertEquals(8, partitionWith8R8WPermNone.stream().filter(a -> a.getPermission() == Permission.NONE).count());
    assertEquals(0, partitionWith8R8WPermNone.stream().filter(a -> a.getPermission() == Permission.READ).count());
    assertEquals(0, partitionWith8R8WPermNone.stream().filter(a -> a.getPermission() == Permission.WRITE).count());
    assertEquals(0, partitionWith8R8WPermNone.stream().filter(a -> a.getPermission() == Permission.READ_WRITE).count());
}

@Test
public void testBinarySearchInQueueByTime() {

    // replace provider, need new factory again
    storeConfig.setTieredBackendServiceProvider(PosixFileSegment.class.getName());
    flatFileFactory = new FlatFileFactory(metadataStore, storeConfig);

    // inject store time: 0, +100, +100, +100, +200
    MessageQueue mq = new MessageQueue("TopicTest", "BrokerName", 1);
    FlatMessageFile flatFile = new FlatMessageFile(flatFileFactory, MessageStoreUtil.toFilePath(mq));
    flatFile.initOffset(50);
    long timestamp1 = 1000;
    ByteBuffer buffer = MessageFormatUtilTest.buildMockedMessageBuffer();
    buffer.putLong(MessageFormatUtil.QUEUE_OFFSET_POSITION, 50);
    buffer.putLong(MessageFormatUtil.STORE_TIMESTAMP_POSITION, timestamp1);
    flatFile.appendCommitLog(buffer);

    long timestamp2 = timestamp1 + 100;
    buffer = MessageFormatUtilTest.buildMockedMessageBuffer();
    buffer.putLong(MessageFormatUtil.QUEUE_OFFSET_POSITION, 51);
    buffer.putLong(MessageFormatUtil.STORE_TIMESTAMP_POSITION, timestamp2);
    flatFile.appendCommitLog(buffer);
    buffer = MessageFormatUtilTest.buildMockedMessageBuffer();
    buffer.putLong(MessageFormatUtil.QUEUE_OFFSET_POSITION, 52);
    buffer.putLong(MessageFormatUtil.STORE_TIMESTAMP_POSITION, timestamp2);
    flatFile.appendCommitLog(buffer);
    buffer = MessageFormatUtilTest.buildMockedMessageBuffer();
    buffer.putLong(MessageFormatUtil.QUEUE_OFFSET_POSITION, 53);
    buffer.putLong(MessageFormatUtil.STORE_TIMESTAMP_POSITION, timestamp2);
    flatFile.appendCommitLog(buffer);

    long timestamp3 = timestamp2 + 100;
    buffer = MessageFormatUtilTest.buildMockedMessageBuffer();
    buffer.putLong(MessageFormatUtil.QUEUE_OFFSET_POSITION, 54);
    buffer.putLong(MessageFormatUtil.STORE_TIMESTAMP_POSITION, timestamp3);
    flatFile.appendCommitLog(buffer);

    // append message to consume queue
    flatFile.consumeQueue.initOffset(50 * ConsumeQueue.CQ_STORE_UNIT_SIZE);

    for (int i = 0; i < 5; i++) {
        AppendResult appendResult = flatFile.appendConsumeQueue(new DispatchRequest(
            mq.getTopic(), mq.getQueueId(), MessageFormatUtilTest.MSG_LEN * i,
            MessageFormatUtilTest.MSG_LEN, 0, timestamp1, 50 + i,
            "", "", 0, 0, null));
        Assert.assertEquals(AppendResult.SUCCESS, appendResult);
    }

    // commit message will increase max consume queue offset
    Assert.assertTrue(flatFile.commitAsync().join());

    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp3 + 1, BoundaryType.UPPER).join().longValue());
    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp3, BoundaryType.UPPER).join().longValue());

    Assert.assertEquals(50, flatFile.getQueueOffsetByTimeAsync(timestamp1 - 1, BoundaryType.LOWER).join().longValue());
    Assert.assertEquals(50, flatFile.getQueueOffsetByTimeAsync(timestamp1, BoundaryType.LOWER).join().longValue());

    Assert.assertEquals(51, flatFile.getQueueOffsetByTimeAsync(timestamp1 + 1, BoundaryType.LOWER).join().longValue());
    Assert.assertEquals(51, flatFile.getQueueOffsetByTimeAsync(timestamp2, BoundaryType.LOWER).join().longValue());
    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp2 + 1, BoundaryType.LOWER).join().longValue());
    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp3, BoundaryType.LOWER).join().longValue());

    Assert.assertEquals(50, flatFile.getQueueOffsetByTimeAsync(timestamp1, BoundaryType.UPPER).join().longValue());
    Assert.assertEquals(51, flatFile.getQueueOffsetByTimeAsync(timestamp1 + 1, BoundaryType.UPPER).join().longValue());
    Assert.assertEquals(53, flatFile.getQueueOffsetByTimeAsync(timestamp2, BoundaryType.UPPER).join().longValue());
    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp2 + 1, BoundaryType.UPPER).join().longValue());

    Assert.assertEquals(50, flatFile.getQueueOffsetByTimeAsync(timestamp1 - 1, BoundaryType.UPPER).join().longValue());
    Assert.assertEquals(54, flatFile.getQueueOffsetByTimeAsync(timestamp3 + 1, BoundaryType.LOWER).join().longValue());

    flatFile.destroy();
}

